/**
 * config.js
 *
 * Central configuration module.
 * TLS certificate paths are read exclusively from environment variables so
 * that no secrets or file-system paths are ever hard-coded.
 *
 * Environment variables
 * ─────────────────────
 * TLS_CERT_PATH  – Absolute (or relative) path to the PEM-encoded TLS certificate file.
 * TLS_KEY_PATH   – Absolute (or relative) path to the PEM-encoded private-key file.
 * HTTP_PORT      – Port for the plain-HTTP server (default: 3000).
 * HTTPS_PORT     – Port for the HTTPS server          (default: 3443).
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Port configuration ────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS configuration ─────────────────────────────────────────────────────────

/**
 * Resolves a raw path string from an environment variable into an absolute
 * path and verifies the file is readable before trusting it.
 *
 * @param {string} envVar  - Name of the environment variable.
 * @returns {string|null}  - Absolute path when the file exists, null otherwise.
 */
function resolveFilePath(envVar) {
  const raw = process.env[envVar];
  if (!raw || raw.trim() === '') {
    return null;
  }

  const resolved = path.resolve(raw.trim());

  try {
    fs.accessSync(resolved, fs.constants.R_OK);
    return resolved;
  } catch {
    console.warn(
      `[config] Warning: ${envVar}="${raw}" resolved to "${resolved}" but the file ` +
      `is missing or not readable. HTTPS will be disabled.`
    );
    return null;
  }
}

/**
 * Loads TLS credentials from the paths supplied via environment variables.
 *
 * Returns an object with `cert` and `key` Buffer values when both files are
 * present and readable, or `null` when either is unavailable.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 */
function loadTlsCredentials() {
  const certPath = resolveFilePath('TLS_CERT_PATH');
  const keyPath  = resolveFilePath('TLS_KEY_PATH');

  if (!certPath || !keyPath) {
    return null;
  }

  try {
    const cert = fs.readFileSync(certPath);
    const key  = fs.readFileSync(keyPath);
    return { cert, key };
  } catch (err) {
    console.warn(
      `[config] Warning: Could not read TLS files — ${err.message}. ` +
      `HTTPS will be disabled.`
    );
    return null;
  }
}

// ── Exported configuration object ────────────────────────────────────────────

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,

  /**
   * TLS credentials ({ cert, key }) or null when certs are unavailable.
   * Evaluated once at start-up so file-system errors surface early.
   */
  tls: loadTlsCredentials(),
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour
 * ─────────
 * • Always starts an HTTP server on HTTP_PORT  (default 3000).
 * • Starts an HTTPS server on HTTPS_PORT (default 3443) only when valid TLS
 *   certificate and key paths are supplied via the TLS_CERT_PATH and
 *   TLS_KEY_PATH environment variables (see config.js).
 * • Falls back gracefully to HTTP-only when certs are absent or unreadable,
 *   logging a clear warning so the omission is never silent.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ────────────────────────────────────────────────────────────

/**
 * Wraps server.listen in a Promise so start-up errors (e.g. EADDRINUSE) are
 * surfaced consistently rather than crashing via an uncaught 'error' event.
 *
 * @param {http.Server|https.Server} server
 * @param {number} port
 * @returns {Promise<void>}
 */
function listenAsync(server, port) {
  return new Promise((resolve, reject) => {
    server.listen(port, () => resolve());
    server.once('error', reject);
  });
}

/**
 * Creates and starts all servers, then returns them so callers (e.g. tests)
 * can shut them down cleanly.
 *
 * @returns {Promise<{ httpServer: http.Server, httpsServer: https.Server|null }>}
 */
async function startServers() {
  // ── HTTP (always started) ──────────────────────────────────────────────────
  const httpServer = http.createServer(app);
  await listenAsync(httpServer, config.HTTP_PORT);
  console.log(`[app] HTTP  server listening on port ${config.HTTP_PORT}`);

  // ── HTTPS (started only when TLS credentials are available) ───────────────
  let httpsServer = null;

  if (config.tls) {
    httpsServer = https.createServer(config.tls, app);
    await listenAsync(httpsServer, config.HTTPS_PORT);
    console.log(`[app] HTTPS server listening on port ${config.HTTPS_PORT}`);
  } else {
    console.warn(
      '[app] TLS credentials not available — ' +
      'set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS. ' +
      'Running HTTP-only.'
    );
  }

  return { httpServer, httpsServer };
}

// Start servers only when this module is run directly (not required by tests).
if (require.main === module) {
  startServers().catch((err) => {
    console.error('[app] Failed to start server:', err);
    process.exit(1);
  });
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = { app, startServers };

