  const c = require('./config');
  console.assert(c.HTTP_PORT  === 3000,  'HTTP_PORT  default');
  console.assert(c.HTTPS_PORT === 3443,  'HTTPS_PORT default');
  console.assert(c.tlsConfig  === null,  'tlsConfig null when no env vars');
