/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour is driven entirely by two environment variables:
 *   TLS_CERT_PATH  – absolute (or relative) path to the PEM certificate file
 *   TLS_KEY_PATH   – absolute (or relative) path to the PEM private-key file
 *
 * When both variables are set the values are validated:
 *   • Neither path may be empty or whitespace-only.
 *   • Both files must exist and be readable before the config is exported.
 *
 * If either variable is missing, or if the files cannot be read, TLS is
 * disabled and the application falls back to HTTP-only mode.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS certificate loading ───────────────────────────────────────────────────

/**
 * Attempts to read a file synchronously.
 * Returns the Buffer on success, or null when the file is absent / unreadable.
 *
 * @param {string} filePath
 * @param {string} label    – human-readable name used in log messages
 * @returns {Buffer|null}
 */
function tryReadFile(filePath, label) {
  try {
    return fs.readFileSync(filePath);
  } catch (err) {
    console.error(
      `[config] Cannot read ${label} at "${filePath}": ${err.message}`
    );
    return null;
  }
}

/**
 * Resolves TLS options from environment variables.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 *   A tls-options object when both files are available, otherwise null.
 */
function resolveTlsOptions() {
  const certPath = (process.env.TLS_CERT_PATH || '').trim();
  const keyPath  = (process.env.TLS_KEY_PATH  || '').trim();

  // Both variables must be present and non-empty.
  if (!certPath || !keyPath) {
    if (certPath || keyPath) {
      // One is set but the other is not — warn so the operator can fix it.
      console.warn(
        '[config] TLS disabled: both TLS_CERT_PATH and TLS_KEY_PATH must be ' +
        'set. Only %s is currently defined.',
        certPath ? 'TLS_CERT_PATH' : 'TLS_KEY_PATH'
      );
    }
    return null;
  }

  // Resolve relative paths against the working directory.
  const absCertPath = path.resolve(certPath);
  const absKeyPath  = path.resolve(keyPath);

  const cert = tryReadFile(absCertPath, 'TLS certificate');
  const key  = tryReadFile(absKeyPath,  'TLS private key');

  if (!cert || !key) {
    console.warn('[config] TLS disabled: one or more certificate files could not be read.');
    return null;
  }

  return { cert, key };
}

// ── Exported configuration ───────────────────────────────────────────────────

const tlsOptions = resolveTlsOptions();

module.exports = {
  /** Port for the plain-HTTP server. */
  HTTP_PORT,

  /** Port for the HTTPS server (only used when tlsOptions is non-null). */
  HTTPS_PORT,

  /**
   * TLS options ready to be passed directly to `https.createServer()`.
   * `null` when certificates are unavailable — indicates HTTP-only mode.
   *
   * @type {{ cert: Buffer, key: Buffer }|null}
   */
  tlsOptions,
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Server startup behaviour:
 *   • HTTP  (port 3000 by default) – always started.
 *   • HTTPS (port 3443 by default) – started only when TLS_CERT_PATH and
 *     TLS_KEY_PATH environment variables point to readable certificate files.
 *
 * Port defaults can be overridden via HTTP_PORT / HTTPS_PORT env vars.
 * All TLS configuration is handled by the config module (config.js).
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ───────────────────────────────────────────────────────────

/**
 * Starts the HTTP and (optionally) HTTPS servers.
 *
 * Separated from the module-level code so that tests can import the Express
 * `app` without triggering real network listeners.
 *
 * @returns {{ httpServer: http.Server, httpsServer: https.Server|null }}
 */
function startServers() {
  // Always start HTTP.
  const httpServer = http.createServer(app);
  httpServer.listen(config.HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
  });

  // Start HTTPS only when valid certificates are available.
  let httpsServer = null;

  if (config.tlsOptions) {
    httpsServer = https.createServer(config.tlsOptions, app);
    httpsServer.listen(config.HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${config.HTTPS_PORT}`);
    });
  } else {
    console.log(
      '[https] No TLS certificates configured — skipping HTTPS server. ' +
      'Set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.'
    );
  }

  return { httpServer, httpsServer };
}

// Start servers when this file is run directly (node app.js).
// When required by tests the caller controls whether startServers() is invoked.
if (require.main === module) {
  startServers();
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = { app, startServers };

