/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour is controlled by two environment variables:
 *   TLS_CERT_PATH  – absolute or relative path to the PEM-encoded certificate file
 *   TLS_KEY_PATH   – absolute or relative path to the PEM-encoded private-key file
 *
 * Both variables must be set AND the files must be readable for HTTPS to be
 * enabled. If either variable is missing the server starts in HTTP-only mode.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS certificate loading ───────────────────────────────────────────────────

/**
 * Attempt to read TLS credentials from the paths supplied via environment
 * variables.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 *   The raw file contents if both files are readable, otherwise `null`.
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both env vars must be present.
  if (!certPath || !keyPath) {
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  try {
    const cert = fs.readFileSync(resolvedCert);
    const key  = fs.readFileSync(resolvedKey);
    return { cert, key };
  } catch (err) {
    // Surface a descriptive warning so operators know why HTTPS did not start.
    console.warn(
      `[config] HTTPS disabled – could not read TLS files: ${err.message}`
    );
    return null;
  }
}

// Evaluate once at startup so the rest of the application gets a stable object.
const tlsCredentials = loadTlsCredentials();

// ── Exported configuration object ────────────────────────────────────────────

module.exports = {
  /** Port for the plain-HTTP server. */
  HTTP_PORT,

  /** Port for the HTTPS server (only used when TLS credentials are available). */
  HTTPS_PORT,

  /**
   * TLS credentials `{ cert, key }` when both env vars are set and the files
   * are readable; `null` otherwise.
   */
  tlsCredentials,

  /**
   * Convenience flag – `true` when the server should also bind an HTTPS
   * listener.
   */
  httpsEnabled: tlsCredentials !== null,
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour:
 *   • Always starts an HTTP server on HTTP_PORT (default 3000).
 *   • When TLS_CERT_PATH and TLS_KEY_PATH are set and both files are readable,
 *     also starts an HTTPS server on HTTPS_PORT (default 3443).
 *   • Falls back to HTTP-only with a clear console warning when certs are
 *     missing or unreadable.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

// ── Express application ───────────────────────────────────────────────────────

const app = express();
app.use(express.json());

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup (skipped when this file is required by tests) ─────────────

if (require.main === module) {
  // Always start the HTTP server.
  const httpServer = http.createServer(app);
  httpServer.listen(config.HTTP_PORT, () => {
    console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
  });

  if (config.httpsEnabled) {
    // TLS credentials are available – start the HTTPS server.
    const httpsServer = https.createServer(config.tlsCredentials, app);
    httpsServer.listen(config.HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${config.HTTPS_PORT}`);
    });
  } else {
    // Certs not configured or unreadable – warn and continue HTTP-only.
    console.warn(
      '[https] HTTPS is disabled. Set TLS_CERT_PATH and TLS_KEY_PATH to enable it.'
    );
  }
}

module.exports = app;

