/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour is driven by two environment variables:
 *   TLS_CERT_PATH  – absolute or relative path to the PEM certificate file
 *   TLS_KEY_PATH   – absolute or relative path to the PEM private-key file
 *
 * Both variables must be set AND the files must be readable for HTTPS to be
 * enabled.  Any other combination silently falls back to HTTP-only.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ─────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS ───────────────────────────────────────────────────────────────────────

/**
 * Resolve an environment-supplied path to an absolute path, then read it.
 * Returns the file's Buffer on success, or null on any failure.
 *
 * @param {string|undefined} envValue  Raw value from process.env
 * @param {string}           label     Human-readable name used in log messages
 * @returns {Buffer|null}
 */
function readCertFile(envValue, label) {
  if (!envValue) {
    return null;
  }

  const resolved = path.resolve(envValue);

  try {
    const buf = fs.readFileSync(resolved);
    console.log(`[config] Loaded ${label}: ${resolved}`);
    return buf;
  } catch (err) {
    console.warn(
      `[config] Could not read ${label} at "${resolved}": ${err.message}`,
    );
    return null;
  }
}

const certBuffer = readCertFile(process.env.TLS_CERT_PATH, 'TLS_CERT_PATH');
const keyBuffer  = readCertFile(process.env.TLS_KEY_PATH,  'TLS_KEY_PATH');

/**
 * tlsOptions is null when certs are unavailable, or a ready-to-use options
 * object for https.createServer() when both files loaded successfully.
 *
 * @type {{ cert: Buffer, key: Buffer }|null}
 */
const tlsOptions = certBuffer && keyBuffer
  ? { cert: certBuffer, key: keyBuffer }
  : null;

if (tlsOptions) {
  console.log('[config] TLS credentials loaded — HTTPS will be enabled.');
} else {
  console.log(
    '[config] TLS credentials unavailable — starting in HTTP-only mode.',
  );
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,
  /** @type {{ cert: Buffer, key: Buffer }|null} */
  tlsOptions,
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour at startup
 * ─────────────────────
 *  • HTTP  is always started on HTTP_PORT  (default 3000).
 *  • HTTPS is started on HTTPS_PORT (default 3443) only when valid TLS
 *    certificate and key paths are supplied via the TLS_CERT_PATH and
 *    TLS_KEY_PATH environment variables and the files are readable.
 *
 * See config.js for the full configuration reference.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');

const { HTTP_PORT, HTTPS_PORT, tlsOptions } = require('./config');

// ── Express application ───────────────────────────────────────────────────────

const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ────────────────────────────────────────────────────────────

/**
 * Start the HTTP server.  Always runs, regardless of TLS availability.
 */
function startHttp() {
  const server = http.createServer(app);

  server.listen(HTTP_PORT, () => {
    console.log(`[http]  Server listening  → http://localhost:${HTTP_PORT}`);
  });

  server.on('error', (err) => {
    console.error(`[http]  Server error: ${err.message}`);
  });

  return server;
}

/**
 * Start the HTTPS server using the TLS options from config.js.
 * Called only when tlsOptions is non-null.
 */
function startHttps() {
  const server = https.createServer(tlsOptions, app);

  server.listen(HTTPS_PORT, () => {
    console.log(`[https] Server listening  → https://localhost:${HTTPS_PORT}`);
  });

  server.on('error', (err) => {
    console.error(`[https] Server error: ${err.message}`);
  });

  return server;
}

// Start HTTP unconditionally, HTTPS only when certs are available.
const httpServer  = startHttp();
const httpsServer = tlsOptions ? startHttps() : null;

if (!tlsOptions) {
  console.log(
    '[app]   HTTPS is disabled — set TLS_CERT_PATH and TLS_KEY_PATH to enable it.',
  );
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = { app, httpServer, httpsServer };

