/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour is controlled entirely by two environment variables:
 *   TLS_CERT_PATH  – absolute (or relative) path to the PEM certificate file
 *   TLS_KEY_PATH   – absolute (or relative) path to the PEM private-key file
 *
 * Both variables must be set AND the files must be readable for HTTPS to be
 * enabled.  If either variable is missing the server starts in HTTP-only mode
 * and a descriptive message is printed to stdout.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ─────────────────────────────────────────────────────────────────────
const HTTP_PORT  = 3000;
const HTTPS_PORT = 3443;

// ── TLS certificate loading ───────────────────────────────────────────────────

/**
 * Attempt to read a file synchronously and return its contents as a Buffer.
 * Returns null and prints a warning when the path is falsy or unreadable.
 *
 * @param {string} envVar  – name of the environment variable (for diagnostics)
 * @param {string} filePath – value of that environment variable
 * @returns {Buffer|null}
 */
function readFileOrNull(envVar, filePath) {
  if (!filePath) {
    console.warn(`[config] ${envVar} is not set – skipping TLS.`);
    return null;
  }

  const resolved = path.resolve(filePath);

  try {
    return fs.readFileSync(resolved);
  } catch (err) {
    console.warn(
      `[config] Cannot read file referenced by ${envVar} ("${resolved}"): ${err.message}`
    );
    return null;
  }
}

/**
 * Build the TLS options object expected by Node's https.createServer().
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 *   Returns a populated options object when both files are readable,
 *   or null when HTTPS should not be started.
 */
function loadTlsOptions() {
  const cert = readFileOrNull('TLS_CERT_PATH', process.env.TLS_CERT_PATH);
  const key  = readFileOrNull('TLS_KEY_PATH',  process.env.TLS_KEY_PATH);

  if (!cert || !key) {
    return null;   // at least one piece is unavailable → HTTP-only mode
  }

  return { cert, key };
}

// ── Exported configuration ────────────────────────────────────────────────────
module.exports = {
  HTTP_PORT,
  HTTPS_PORT,

  /**
   * Pre-loaded TLS options ({ cert, key }) or null when certs are unavailable.
   * Evaluated once at startup so the file system is not hit on every request.
   */
  tlsOptions: loadTlsOptions(),
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Ports and TLS options are supplied by config.js, which reads:
 *   TLS_CERT_PATH  – path to PEM certificate
 *   TLS_KEY_PATH   – path to PEM private key
 *
 * Start-up behaviour:
 *   • Both variables set and files readable → HTTP (3000) + HTTPS (3443)
 *   • Either variable missing or file unreadable → HTTP-only (3000)
 */

'use strict';

const http  = require('http');
const https = require('https');

const express = require('express');
const config  = require('./config');

const app = express();

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
