/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour is driven by two environment variables:
 *   TLS_CERT_PATH  – absolute or relative path to the PEM certificate file
 *   TLS_KEY_PATH   – absolute or relative path to the PEM private-key file
 *
 * Both variables must be set AND the files must be readable for HTTPS to be
 * enabled.  If either variable is missing the server starts in HTTP-only mode.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ─────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  ?? '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT ?? '3443', 10);

// ── TLS certificate loader ────────────────────────────────────────────────────

/**
 * Attempts to load TLS credentials from the paths supplied via environment
 * variables.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 *   An object containing the raw cert and key buffers when both are available
 *   and readable, or `null` when HTTPS should not be started.
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both variables must be present.
  if (!certPath || !keyPath) {
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  try {
    // Verify the files are accessible before handing them to the TLS stack.
    fs.accessSync(resolvedCert, fs.constants.R_OK);
    fs.accessSync(resolvedKey,  fs.constants.R_OK);

    return {
      cert: fs.readFileSync(resolvedCert),
      key:  fs.readFileSync(resolvedKey),
    };
  } catch (err) {
    // Surface a descriptive warning so operators know why HTTPS did not start.
    console.warn(
      `[config] HTTPS disabled – could not read TLS files: ${err.message}`,
    );
    return null;
  }
}

// ── Exported configuration object ────────────────────────────────────────────

module.exports = {
  HTTP_PORT,
  HTTPS_PORT,

  /**
   * Lazily resolved TLS credentials.
   * Evaluated once when this module is first `require()`-d so that tests can
   * set environment variables before importing.
   */
  tls: loadTlsCredentials(),
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Port defaults:
 *   HTTP  → 3000  (override via HTTP_PORT env var)
 *   HTTPS → 3443  (override via HTTPS_PORT env var)
 *
 * HTTPS is only started when TLS_CERT_PATH and TLS_KEY_PATH are set to
 * readable PEM files (see config.js).  The process falls back to HTTP-only
 * when the certificate files are absent or unreadable.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup (skipped when loaded by tests via require()) ───────────────

/**
 * Starts the HTTP and, when TLS credentials are available, HTTPS servers.
 *
 * Returns an object with the started server instance(s) so that callers
 * (e.g. integration tests) can close them programmatically.
 *
 * @returns {{ httpServer: http.Server, httpsServer: https.Server|null }}
 */
function startServers() {
  // Always start HTTP.
  const httpServer = http
    .createServer(app)
    .listen(config.HTTP_PORT, () => {
      console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
    });

  // Only start HTTPS when valid credentials were loaded by config.js.
  let httpsServer = null;

  if (config.tls) {
    httpsServer = https
      .createServer({ cert: config.tls.cert, key: config.tls.key }, app)
      .listen(config.HTTPS_PORT, () => {
        console.log(`[https] Server listening on https://localhost:${config.HTTPS_PORT}`);
      });
  } else {
    console.log(
      '[https] TLS credentials not configured – running in HTTP-only mode. ' +
      'Set TLS_CERT_PATH and TLS_KEY_PATH to enable HTTPS.',
    );
  }

  return { httpServer, httpsServer };
}

// Start servers only when this file is run directly (not require()-d by tests).
if (require.main === module) {
  startServers();
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = { app, startServers };

