/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour
 * ─────────────
 * Set the following environment variables to enable HTTPS:
 *
 *   TLS_CERT_PATH  – absolute (or relative) path to the PEM-encoded certificate file
 *   TLS_KEY_PATH   – absolute (or relative) path to the PEM-encoded private-key file
 *
 * Both variables must be present and point to readable files for HTTPS to be
 * activated.  If either variable is missing the server falls back to HTTP-only.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ──────────────────────────────────────────────────────────────────────
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS ────────────────────────────────────────────────────────────────────────

/**
 * Attempt to load TLS credentials from the paths supplied via environment
 * variables.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 *   The raw file contents on success, or `null` when certs are unavailable.
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both variables must be set.
  if (!certPath || !keyPath) {
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  // Both files must exist before we try to read them so we can emit a clear
  // warning rather than an unhandled ENOENT exception.
  const certExists = fs.existsSync(resolvedCert);
  const keyExists  = fs.existsSync(resolvedKey);

  if (!certExists || !keyExists) {
    const missing = [
      !certExists && `TLS_CERT_PATH (${resolvedCert})`,
      !keyExists  && `TLS_KEY_PATH  (${resolvedKey})`,
    ].filter(Boolean).join(', ');

    console.warn(
      `[config] TLS disabled — the following file(s) could not be found: ${missing}`
    );
    return null;
  }

  try {
    return {
      cert: fs.readFileSync(resolvedCert),
      key:  fs.readFileSync(resolvedKey),
    };
  } catch (err) {
    console.warn(`[config] TLS disabled — failed to read certificate files: ${err.message}`);
    return null;
  }
}

// Evaluate once at start-up so the rest of the application gets a stable value.
const tlsCredentials = loadTlsCredentials();

// ── Exports ────────────────────────────────────────────────────────────────────
module.exports = {
  HTTP_PORT,
  HTTPS_PORT,

  /**
   * `true` when valid TLS credentials were loaded and HTTPS should be started.
   * @type {boolean}
   */
  TLS_ENABLED: tlsCredentials !== null,

  /**
   * TLS options object ready to pass directly to `https.createServer()`, or
   * `null` when TLS is not available.
   * @type {{ cert: Buffer, key: Buffer }|null}
   */
  tlsCredentials,
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour
 * ─────────
 *  • HTTP  always starts on HTTP_PORT  (default 3000).
 *  • HTTPS starts on HTTPS_PORT (default 3443) only when TLS certificate paths
 *    are supplied via TLS_CERT_PATH and TLS_KEY_PATH environment variables AND
 *    both files can be read successfully.
 *  • When certs are unavailable the server falls back gracefully to HTTP-only
 *    and logs a clear informational message.
 *
 * See config.js for full environment-variable documentation.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');

const { HTTP_PORT, HTTPS_PORT, TLS_ENABLED, tlsCredentials } = require('./config');

const app = express();

// ── Routes ─────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ─────────────────────────────────────────────────────────────

/**
 * Start the HTTP server.
 * Always started regardless of TLS availability.
 */
const httpServer = http.createServer(app);

httpServer.listen(HTTP_PORT, () => {
  console.log(`[http]  Server listening on http://localhost:${HTTP_PORT}`);
});

/**
 * Start the HTTPS server only when valid TLS credentials are present.
 */
if (TLS_ENABLED) {
  const httpsServer = https.createServer(tlsCredentials, app);

  httpsServer.listen(HTTPS_PORT, () => {
    console.log(`[https] Server listening on https://localhost:${HTTPS_PORT}`);
  });
} else {
  console.log('[https] TLS credentials not available — running HTTP only.');
}

// ── Exports ────────────────────────────────────────────────────────────────────

module.exports = app;

