/**
 * config.js
 *
 * Central configuration module.
 *
 * TLS behaviour is driven by two environment variables:
 *   TLS_CERT_PATH – absolute or relative path to the PEM-encoded certificate file
 *   TLS_KEY_PATH  – absolute or relative path to the PEM-encoded private-key file
 *
 * Both variables must be set AND the files must be readable for HTTPS to be
 * enabled.  If either variable is missing the config is returned with
 * `tls: null` and the caller should fall back to HTTP-only mode.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Ports ─────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ── TLS ───────────────────────────────────────────────────────────────────────

/**
 * Attempts to load TLS credentials from the paths supplied via environment
 * variables.
 *
 * @returns {{ cert: Buffer, key: Buffer }|null}
 *   A credentials object ready to be spread into `https.createServer()`, or
 *   `null` when the environment variables are absent or the files cannot be
 *   read.
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both variables must be provided.
  if (!certPath || !keyPath) {
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  try {
    const cert = fs.readFileSync(resolvedCert);
    const key  = fs.readFileSync(resolvedKey);
    return { cert, key };
  } catch (err) {
    // Surface a descriptive warning so operators can diagnose misconfiguration
    // without crashing the process.
    console.warn(
      '[config] Warning: TLS_CERT_PATH / TLS_KEY_PATH are set but the files ' +
      `could not be read – falling back to HTTP only.\n  ${err.message}`
    );
    return null;
  }
}

// ── Exported configuration ────────────────────────────────────────────────────

const config = {
  /** Port the HTTP server will listen on. */
  httpPort: HTTP_PORT,

  /** Port the HTTPS server will listen on (only used when tls !== null). */
  httpsPort: HTTPS_PORT,

  /**
   * TLS credentials ({ cert, key }) when both env vars are set and readable,
   * otherwise null.
   */
  tls: loadTlsCredentials(),
};

module.exports = config;

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Start-up behaviour
 * ──────────────────
 *   • HTTP  (port 3000 by default) – always started.
 *   • HTTPS (port 3443 by default) – started only when TLS_CERT_PATH and
 *     TLS_KEY_PATH environment variables point to readable PEM files.
 *
 * See config.js for all tunable parameters.
 */

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Server startup ────────────────────────────────────────────────────────────

/**
 * Starts the HTTP and (optionally) HTTPS servers.
 *
 * Separated from the module-level code so that test suites can import the
 * Express `app` without automatically binding to ports.
 *
 * @returns {{ httpServer: http.Server, httpsServer: https.Server|null }}
 */
function startServers() {
  // Always start HTTP.
  const httpServer = http.createServer(app);
  httpServer.listen(config.httpPort, () => {
    console.log(`[http]  Server listening on http://localhost:${config.httpPort}`);
  });

  // Start HTTPS only when valid TLS credentials are available.
  let httpsServer = null;

  if (config.tls) {
    httpsServer = https.createServer(config.tls, app);
    httpsServer.listen(config.httpsPort, () => {
      console.log(`[https] Server listening on https://localhost:${config.httpsPort}`);
    });
  } else {
    console.log(
      '[https] TLS credentials not configured – HTTPS disabled. ' +
      'Set TLS_CERT_PATH and TLS_KEY_PATH to enable.'
    );
  }

  return { httpServer, httpsServer };
}

// Start servers automatically unless the module is loaded by a test runner
// (tests import the file and manage server lifecycle themselves).
/* istanbul ignore next */
if (require.main === module) {
  startServers();
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = { app, startServers };

