//   TLS_KEY_PATH   – absolute or relative path to the PEM private-key file

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Ports ────────────────────────────────────────────────────────────────────

const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ─── TLS ──────────────────────────────────────────────────────────────────────

/**
 * Attempt to load TLS credentials defined by TLS_CERT_PATH / TLS_KEY_PATH.
 *
 * Returns an object with { cert, key } Buffer values on success, or null when
 * either variable is absent or the files cannot be read.  Errors are reported
 * to stderr but are never fatal so the server can always fall back to HTTP.
 *
 * @returns {{ cert: Buffer, key: Buffer } | null}
 */
function loadTlsCredentials() {
  const certPath = process.env.TLS_CERT_PATH;
  const keyPath  = process.env.TLS_KEY_PATH;

  // Both variables must be set; missing either means TLS is not configured.
  if (!certPath || !keyPath) {
    return null;
  }

  const resolvedCert = path.resolve(certPath);
  const resolvedKey  = path.resolve(keyPath);

  try {
    const cert = fs.readFileSync(resolvedCert);
    const key  = fs.readFileSync(resolvedKey);
    return { cert, key };
  } catch (err) {
    console.error(
      `[config] Failed to load TLS credentials: ${err.message}\n` +
      `  TLS_CERT_PATH → ${resolvedCert}\n` +
      `  TLS_KEY_PATH  → ${resolvedKey}\n` +
      '  Falling back to HTTP-only mode.'
    );
    return null;
  }
}

