//
// Behaviour:
//   • Always starts an HTTP server on HTTP_PORT  (default 3000).
//   • Starts an HTTPS server on HTTPS_PORT (default 3443) only when valid TLS
//     certificate and key paths are supplied via the TLS_CERT_PATH and
//     TLS_KEY_PATH environment variables and the files are readable.
//   • Falls back gracefully to HTTP-only when certs are unavailable.

'use strict';

const http    = require('http');
const https   = require('https');
const express = require('express');
const config  = require('./config');

const app = express();

// ─── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ─── Server startup ───────────────────────────────────────────────────────────

/**
 * Start the HTTP server (always).
 */
function startHttp() {
  return new Promise((resolve, reject) => {
    const server = http.createServer(app);

    server.listen(config.HTTP_PORT, () => {
      console.log(`[http]  Server listening on http://localhost:${config.HTTP_PORT}`);
      resolve(server);
    });

    server.on('error', reject);
  });
}

/**
 * Start the HTTPS server when TLS credentials are available.
 * Returns null (without throwing) when credentials are absent.
 */
function startHttps() {
  if (!config.tlsCredentials) {
    console.warn(
      '[https] TLS credentials not configured or unreadable — ' +
      'skipping HTTPS server. Set TLS_CERT_PATH and TLS_KEY_PATH to enable it.'
    );
    return Promise.resolve(null);
  }

  return new Promise((resolve, reject) => {
    const server = https.createServer(config.tlsCredentials, app);

    server.listen(config.HTTPS_PORT, () => {
      console.log(`[https] Server listening on https://localhost:${config.HTTPS_PORT}`);
      resolve(server);
    });

    server.on('error', reject);
  });
}

/**
 * Boot both servers.  Exported so tests can await full initialisation.
 *
 * @returns {Promise<{ httpServer: http.Server, httpsServer: https.Server | null }>}
 */
async function startServers() {
  const [httpServer, httpsServer] = await Promise.all([startHttp(), startHttps()]);
  return { httpServer, httpsServer };
}

// Only call startServers() when this file is executed directly (not required
// by tests or other modules) so the ports are never bound unintentionally.
if (require.main === module) {
  startServers().catch((err) => {
    console.error('[startup] Fatal error:', err);
    process.exit(1);
  });
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { app, startServers };

