/**
 * config.js
 *
 * Central configuration module.
 * TLS is enabled only when both TLS_CERT_PATH and TLS_KEY_PATH environment
 * variables are set.  All other settings are kept here as named constants so
 * that app.js (and future modules) never have magic numbers or direct
 * process.env calls scattered throughout the codebase.
 */

'use strict';

const path = require('path');

// ---------------------------------------------------------------------------
// Ports
// ---------------------------------------------------------------------------
const HTTP_PORT  = parseInt(process.env.HTTP_PORT  || '3000', 10);
const HTTPS_PORT = parseInt(process.env.HTTPS_PORT || '3443', 10);

// ---------------------------------------------------------------------------
// TLS certificate paths
// Read from environment variables; undefined when not provided.
// ---------------------------------------------------------------------------
const TLS_CERT_PATH = process.env.TLS_CERT_PATH
  ? path.resolve(process.env.TLS_CERT_PATH)
  : undefined;

const TLS_KEY_PATH = process.env.TLS_KEY_PATH
  ? path.resolve(process.env.TLS_KEY_PATH)
  : undefined;

/**
 * Whether HTTPS should be started.
 * Both paths must be present; neither can be an empty string.
 */
const TLS_ENABLED = Boolean(TLS_CERT_PATH && TLS_KEY_PATH);

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = {
  HTTP_PORT,
  HTTPS_PORT,
  TLS_CERT_PATH,
  TLS_KEY_PATH,
  TLS_ENABLED,
};

/**
 * app.js
 *
 * Express application with dual HTTP / HTTPS support.
 *
 * Behaviour
 * ---------
 *  - HTTP  always starts on HTTP_PORT  (default 3000).
 *  - HTTPS starts on HTTPS_PORT (default 3443) only when TLS_CERT_PATH and
 *    TLS_KEY_PATH environment variables point to readable certificate files.
 *  - If the certificate files are configured but cannot be read, the process
 *    logs a clear error and falls back to HTTP-only rather than crashing.
 */

'use strict';

const express = require('express');
const http    = require('http');
const https   = require('https');
const fs      = require('fs');

const { HTTP_PORT, HTTPS_PORT, TLS_CERT_PATH, TLS_KEY_PATH, TLS_ENABLED } =
  require('./config');

// ---------------------------------------------------------------------------
// Express application
// ---------------------------------------------------------------------------
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ---------------------------------------------------------------------------
// HTTP server (always started)
// ---------------------------------------------------------------------------
const httpServer = http.createServer(app);

httpServer.listen(HTTP_PORT, () => {
  console.log(`[HTTP]  Server listening on http://localhost:${HTTP_PORT}`);
});

// ---------------------------------------------------------------------------
// HTTPS server (started only when certificates are available)
// ---------------------------------------------------------------------------
if (TLS_ENABLED) {
  let tlsOptions;

  try {
    tlsOptions = {
      cert: fs.readFileSync(TLS_CERT_PATH),
      key:  fs.readFileSync(TLS_KEY_PATH),
    };
  } catch (err) {
    // Certificate files are configured but unreadable — degrade gracefully.
    console.error(
      `[HTTPS] Failed to read TLS certificate files; falling back to HTTP-only.\n` +
      `        cert: ${TLS_CERT_PATH}\n` +
      `        key : ${TLS_KEY_PATH}\n` +
      `        ${err.message}`
    );
  }

  if (tlsOptions) {
    const httpsServer = https.createServer(tlsOptions, app);

    httpsServer.listen(HTTPS_PORT, () => {
      console.log(`[HTTPS] Server listening on https://localhost:${HTTPS_PORT}`);
    });
  }
} else {
  console.log(
    '[HTTPS] TLS_CERT_PATH / TLS_KEY_PATH not set — running HTTP-only.'
  );
}

// ---------------------------------------------------------------------------
// Exports (useful for testing)
// ---------------------------------------------------------------------------
module.exports = app;

